import { Request, Response } from 'express';
import { CreateProjectInput, ProjectDto } from '../../../application/dto/ProjectDto';
import { UseCase } from '../../../application/ports/UseCase';
import { requiredString } from '../RequestReader';

export class ProjectController {
  constructor(private readonly createProject: UseCase<CreateProjectInput, ProjectDto>) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const project = await this.createProject.execute({ name: requiredString(req.body, 'name') });
    res.status(201).json(project);
  };
}

