import { Request, Response } from 'express';
import { TaskDto } from '../../../application/dto/TaskDto';
import {
  AddTaskInput,
  AssignTaskInput,
  ListProjectTasksInput,
  MarkTaskDoneInput,
} from '../../../application/dto/TaskInputs';
import { UseCase } from '../../../application/ports/UseCase';
import { optionalString, requiredString } from '../RequestReader';

export class TaskController {
  constructor(
    private readonly addTask: UseCase<AddTaskInput, TaskDto>,
    private readonly assignTask: UseCase<AssignTaskInput, TaskDto>,
    private readonly listTasks: UseCase<ListProjectTasksInput, TaskDto[]>,
    private readonly markTaskDone: UseCase<MarkTaskDoneInput, TaskDto>,
  ) {}

  add = async (req: Request, res: Response): Promise<void> => {
    const task = await this.addTask.execute({
      projectId: String(req.params.projectId),
      title: requiredString(req.body, 'title'),
      description: optionalString(req.body, 'description'),
      dueDate: optionalString(req.body, 'dueDate'),
      status: optionalString(req.body, 'status'),
    });
    res.status(201).json(task);
  };

  list = async (req: Request, res: Response): Promise<void> => {
    const tasks = await this.listTasks.execute({
      projectId: String(req.params.projectId),
      status: optionalString(req.query, 'status'),
      assigneeId: optionalString(req.query, 'assigneeId'),
    });
    res.json(tasks);
  };

  assign = async (req: Request, res: Response): Promise<void> => {
    const task = await this.assignTask.execute({
      taskId: String(req.params.taskId),
      userId: requiredString(req.body, 'userId'),
    });
    res.json(task);
  };

  markDone = async (req: Request, res: Response): Promise<void> => {
    const task = await this.markTaskDone.execute({ taskId: String(req.params.taskId) });
    res.json(task);
  };
}

=====SOURCE-END=====

